    if (total.compareTo(settle) != 0) throw unprocessable("BLEND_TOTAL_MISMATCH", "各水源取水量之和 X 不等于申请核销量 Y");
    String params = "BLEND|" + allocationKey + "|" + operator + "|" + allocationVersion + "|" + settle.toPlainString() + "|" + normalized entries "sourceId:amount" joined ",";
