AllocationRow allocation = repository.lockAllocationByKey(allocationKey);
if (allocation == null) throw notFound ALLOCATION_NOT_FOUND;
if (allocation.version() != allocationVersion) throw conflict("ALLOCATION_VERSION_CONFLICT", ...);
if (!STATUS_APPROVED.equals(allocation.status())) throw conflict("ALLOCATION_NOT_APPROVED", ...);
if (allocation.heldAmount().compareTo(settle) < 0) throw unprocessable("ALLOCATION_BALANCE_INSUFFICIENT", "申请剩余额度 X 不足，无法核销 Y");
// lock sources in sorted order
List<SourceRow> locked = new ArrayList<>();
for (entry : normalized.entrySet()) {
    SourceRow s = repository.lockSourceById(entry.getKey());
    if (s == null) throw notFound("SOURCE_NOT_FOUND", ...);
    locked.add(s);
}
// availability check
for (source : locked) {
    BigDecimal amt = normalized.get(source.sourceId());
    if (source.availableAmount().compareTo(amt) < 0)
        throw unprocessable("SOURCE_INSUFFICIENT", "水源 " + id + " 余量 " + fmt(avail) + " 不足，需取水 " + fmt(amt));
}
// salinity check
BigDecimal saltTotal = sum(amt * salinity);
if (allocation.maxSalinityMgL() != null) {
    // avg > limit <=> saltTotal > limit * settle
    if (saltTotal.compareTo(allocation.maxSalinityMgL().multiply(settle)) > 0) {
        BigDecimal avg = saltTotal.divide(settle, 6, HALF_UP);
        throw unprocessable("SALINITY_EXCEEDED", "加权平均盐度 " + fmt(avg) + " 毫克每升，高于申请上限 " + fmt(limit));
    }
}
// deduct
long now = nowNanos();
for (source : locked) {
    int updated = repository.deductSourceAvailable(source.id(), normalized.get(source.sourceId()), now);
    if (updated == 0) throw unprocessable("SOURCE_INSUFFICIENT", ...); // 防御：行锁内不会发生
}
if (repository.deductAllocationHeld(allocation.id(), settle, now) == 0)
    throw unprocessable("ALLOCATION_BALANCE_INSUFFICIENT", ...);
BigDecimal weighted = saltTotal.divide(settle, 6, RoundingMode.HALF_UP);
long snapshotId = repository.insertBlendSnapshot(blendKey, allocationKey, allocationVersion, operator, settle, saltTotal, weighted, now);
for (source : locked) repository.insertBlendLine(snapshotId, source.sourceId(), source.version(), amt, source.salinityMgL());
return toBlendResponse(repository.findSnapshotByBlendKey(blendKey));
