        });
        Future<Integer> f2 = pool.submit(() -> {
            gate.await();
            return blendStatus(blendKey, allocationKey, 1, "4", sources(s1, "4"), "alice");
        });
        gate.countDown();
        int s1Status = f1.get(30, TimeUnit.SECONDS);
        int s2Status = f2.get(30, TimeUnit.SECONDS);
