        assertEquals(new BigDecimal("1.000"), lines.get(0).amount());
        assertEquals(new BigDecimal("500"), lines.get(0).salinityMgL());
        assertEquals("src-b", lines.get(1).sourceId());
        assertEquals(new BigDecimal("3.000"), lines.get(1).amount());
    }
